mapper.select:
/* com.portal.security.authority.AuthorRoleManageMapper.selectAuthorRoleListTotCnt */
SELECT COUNT(*) AS totcnt
  FROM LETTNROLEINFO a
  LEFT OUTER JOIN (
       SELECT AUTHOR_CODE, ROLE_CODE, CREAT_DT
         FROM LETTNAUTHORROLERELATE
        WHERE AUTHOR_CODE = #{searchKeyword}
  ) b
    ON a.ROLE_CODE = b.ROLE_CODE

mapper.insert:
/* com.portal.security.authority.AuthorRoleManageMapper.insertAuthorRole */
INSERT INTO LETTNAUTHORROLERELATE
(
	AUTHOR_CODE, ROLE_CODE, CREAT_DT
)
VALUES
(
	#{authorCode}, #{roleCode}, NOW()
)

mapper.delete:
/* com.portal.security.authority.AuthorRoleManageMapper.deleteAuthorRole */
DELETE FROM LETTNAUTHORROLERELATE
 WHERE AUTHOR_CODE = #{authorCode}
   AND ROLE_CODE   = #{roleCode}
